#include<bits/stdc++.h>
using namespace std;
int main(){
    int N;
    scanf("%d",&N);
    vector<int>par(N+1,0);
    vector<vector<int>>ch(N+1);
    for(int i=2;i<=N;i++){
        scanf("%d",&par[i]);
        ch[par[i]].push_back(i);
    }
    vector<int>leaves;
    vector<int>order;
    // DFS to get leaf order
    function<void(int)> dfs=[&](int u){
        order.push_back(u);
        if(ch[u].empty()){leaves.push_back(u);return;}
        for(int c:ch[u]) dfs(c);
    };
    dfs(1);
    int L=leaves.size();
    // For each leaf, its index in the cycle
    map<int,int>leafIdx;
    for(int i=0;i<L;i++) leafIdx[leaves[i]]=i;
    // next leaf in cycle
    auto nextLeaf=[&](int i)->int{return leaves[(i+1)%L];};

    // For each node v, store the range of leaf indices in its subtree [lf[v], rf[v]]
    vector<int>lf(N+1,-1),rf(N+1,-1);
    for(int i=order.size()-1;i>=0;i--){
        int u=order[i];
        if(ch[u].empty()){lf[u]=rf[u]=leafIdx[u];}
        else{lf[u]=lf[ch[u][0]];rf[u]=rf[ch[u].back()];}
    }

    vector<vector<int>>bags;
    vector<pair<int,int>>edges;
    int K=0;
    auto addBag=[&](vector<int>b)->int{bags.push_back(b);return K++;};

    // For each node, bagId that is its "representative"
    vector<int>rep(N+1,-1);

    for(int i=order.size()-1;i>=0;i--){
        int u=order[i];
        if(ch[u].empty()){
            // leaf: bag = {u, par[u], nextLeaf(leafIdx[u])}
            vector<int>b={u};
            if(par[u])b.push_back(par[u]);
            b.push_back(nextLeaf(leafIdx[u]));
            sort(b.begin(),b.end());b.erase(unique(b.begin(),b.end()),b.end());
            rep[u]=addBag(b);
        } else {
            int prev=-1;
            for(int j=0;j<(int)ch[u].size();j++){
                int c=ch[u][j];
                vector<int>b={u,c};
                if(par[u])b.push_back(par[u]);
                // add the leaf connecting consecutive subtrees
                if(j>0) b.push_back(leaves[lf[c]]);
                sort(b.begin(),b.end());b.erase(unique(b.begin(),b.end()),b.end());
                int id=addBag(b);
                if(prev>=0)edges.push_back({prev,id});
                edges.push_back({id,rep[c]});
                if(j==0)rep[u]=id;
                prev=id;
            }
        }
    }

    printf("%d\n",K);
    for(int i=0;i<K;i++){
        printf("%d",(int)bags[i].size());
        for(int x:bags[i])printf(" %d",x);
        printf("\n");
    }
    for(auto&[a,b]:edges)printf("%d %d\n",a+1,b+1);
}
